<?php
/**
 * Plugin directories inside the uploads area.
 *
 * @package sw-sliderman
 */

declare(strict_types=1);

namespace SW\Slider\Infrastructure;

/**
 * Resolves the plugin's public uploads root `uploads/sw-sliderman/` (per site on multisite).
 *
 * Stored references are always relative to this root; absolute paths and URLs are rebuilt on
 * every request so domain or upload path changes keep working (PLAN.md 8.4). Relative paths are
 * generated by the plugin and checked against a strict pattern before use.
 */
final class UploadPaths {

	private const RELATIVE_PATTERN = '#^(?:artifacts|fonts)/[a-z0-9][a-z0-9._-]{0,120}(?:/[a-z0-9][a-z0-9._-]{0,120}){0,2}$#D';

	public static function is_valid_relative( string $relative ): bool {
		return ! str_contains( $relative, '..' ) && ( 1 === preg_match( self::RELATIVE_PATTERN, $relative ) || 1 === preg_match( '#^fonts/[a-f0-9]{24}/LICENSE\.txt$#D', $relative ) );
	}

	/** Absolute base directory without trailing slash. */
	public static function base_dir(): string {
		$uploads = wp_upload_dir( null, false );
		return rtrim( (string) $uploads['basedir'], '/\\' ) . '/sw-sliderman';
	}

	/** Base URL without trailing slash. */
	public static function base_url(): string {
		$uploads = wp_upload_dir( null, false );
		return rtrim( set_url_scheme( (string) $uploads['baseurl'] ), '/' ) . '/sw-sliderman';
	}

	public static function path( string $relative ): ?string {
		return self::is_valid_relative( $relative ) ? self::base_dir() . '/' . $relative : null;
	}

	public static function url( string $relative ): ?string {
		return self::is_valid_relative( $relative ) ? self::base_url() . '/' . $relative : null;
	}

	/** Fonts must stay on both the public website and editor origin, even with upload offloading. */
	public static function local_font_url( string $relative ): ?string {
		$url = str_starts_with( $relative, 'fonts/' ) ? self::url( $relative ) : null;
		return null !== $url && self::same_origin( $url, home_url( '/' ) ) && self::same_origin( $url, admin_url( '/' ) ) ? $url : null;
	}
	public static function same_origin( string $a, string $b ): bool {
		$first  = wp_parse_url( $a );
		$second = wp_parse_url( $b );
		if ( ! is_array( $first ) || ! is_array( $second ) ) {
			return false;
		}
		$origin = static fn ( array $url ): array => array( strtolower( $url['scheme'] ?? '' ), strtolower( $url['host'] ?? '' ), $url['port'] ?? ( 'https' === ( $url['scheme'] ?? '' ) ? 443 : 80 ) );
		return $origin( $first ) === $origin( $second );
	}

	/** Creates a directory below the root (including the root's index.php marker). */
	public static function ensure_dir( string $absolute ): bool {
		if ( ! wp_mkdir_p( $absolute ) ) {
			return false;
		}
		$index = self::base_dir() . '/index.php';
		if ( ! file_exists( $index ) ) {
			// Prevents directory listings on servers that allow them; not an access control.
			file_put_contents( $index, "<?php\n// Silence is golden.\n" ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_file_put_contents -- small marker file inside our own uploads root.
		}
		return true;
	}
}
